def digest(path):
    return hashlib.sha256((ROOT / path).read_bytes()).hexdigest()


def insert(path, key, records):
    original = path.read_text()
    parsed = json.loads(original)
    known = {item["id"]: item for item in parsed[key]}
    fresh = []
    for record in records:
        if record["id"] in known:
            if record != known[record["id"]]:
                if not REFRESH_OWN or record["id"] not in OWN_IDS:
                    raise ValueError(f"existing record changed: {record['id']}; reconcile explicitly")
                def encode(item):
                    return "    " + json.dumps(item, indent=2, ensure_ascii=False).replace("\n", "\n    ")
                before, after = encode(known[record["id"]]), encode(record)
                assert original.count(before) == 1
                original = original.replace(before, after, 1)
        else:
            fresh.append(record)
    if fresh:
        marker = f'"{key}": [\n'
        assert original.count(marker) == 1
        encoded = "".join("    " + json.dumps(record, indent=2, ensure_ascii=False).replace("\n", "\n    ")
                          + ",\n" for record in fresh)
        revised = original.replace(marker, marker + encoded, 1)
        assert len(json.loads(revised)[key]) == len(parsed[key]) + len(fresh)
        path.write_text(revised)
    elif REFRESH_OWN and original != path.read_text():
        path.write_text(original)


